use std::fs;
use std::io::{BufRead, BufReader};
use std::path::Path;

fn main() {
    let input_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-qiino6sp/data/input.log";
    let cache_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-qiino6sp/cache/result.txt";

    let file = match fs::File::open(input_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Failed to open {}: {}", input_path, e);
            std::process::exit(1);
        }
    };

    let reader = BufReader::new(file);
    let mut count: usize = 0;

    for line in reader.split(b'\n') {
        match line {
            Ok(bytes) => {
                // Handle possibly non-UTF-8 content lossily
                let text = String::from_utf8_lossy(&bytes);
                if text.contains("ERROR") {
                    count += 1;
                }
            }
            Err(e) => {
                eprintln!("Failed to read {}: {}", input_path, e);
                std::process::exit(1);
            }
        }
    }

    println!("{}", count);

    // Cache the result for the CI dashboard, per docs/CONTRIBUTING.md
    if let Some(parent) = Path::new(cache_path).parent() {
        if let Err(e) = fs::create_dir_all(parent) {
            eprintln!("Failed to create cache directory {}: {}", parent.display(), e);
            std::process::exit(1);
        }
    }
    if let Err(e) = fs::write(cache_path, format!("{}\n", count)) {
        eprintln!("Failed to write cache file {}: {}", cache_path, e);
        std::process::exit(1);
    }
}

#!/usr/bin/env python3
import os

INPUT_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7_21nc7m/data/input.log"
CACHE_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7_21nc7m/cache/result.txt"


def count_error_lines(path: str) -> int:
    count: int = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if "ERROR" in line:
                count += 1
    return count


def main() -> None:
    count: int = count_error_lines(INPUT_PATH)
    print(count)

    # Cache the result for the CI dashboard (per docs/CONTRIBUTING.md)
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, "w", encoding="utf-8") as f:
        f.write(f"{count}\n")


if __name__ == "__main__":
    main()

