use std::fs;
use std::io::{BufRead, BufReader};

const INPUT_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-v4_6omxk/data/input.log";
const OVERRIDES_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-v4_6omxk/etc/overrides.conf";

fn load_needle() -> String {
    let mut needle = String::from("ERROR");
    if let Ok(contents) = fs::read_to_string(OVERRIDES_PATH) {
        for line in contents.lines() {
            let line = line.trim_end_matches('\r');
            if let Some(rest) = line.strip_prefix("needle=") {
                if !rest.is_empty() {
                    needle = rest.to_string();
                }
            }
        }
    }
    needle
}

fn main() {
    let needle = load_needle();

    let file = match fs::File::open(INPUT_PATH) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Failed to open {}: {}", INPUT_PATH, e);
            std::process::exit(1);
        }
    };

    let reader = BufReader::new(file);
    let mut count: u64 = 0;

    for line in reader.split(b'\n') {
        match line {
            Ok(bytes) => {
                let text = String::from_utf8_lossy(&bytes);
                if text.contains(&needle) {
                    count += 1;
                }
            }
            Err(e) => {
                eprintln!("Error reading {}: {}", INPUT_PATH, e);
                std::process::exit(1);
            }
        }
    }

    println!("{}", count);
}

import std.io;
import std.buffer;

fn load[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/data/input.log"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/data/input.log")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/data/input.log", out);
}

fn store[&f, &d](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/cache/result.txt"), data: &d [byte]) -> [fs_write("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/cache/result.txt")] int {
    return fs_write(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/cache/result.txt", data);
}

fn say[&i, &b](io: &!i Io, data: &b [byte]) -> [io_write] int {
    return io.write_all(io, data);
}

fn matches_at[&r](s: &r [byte], n: int, i: int) -> [] bool {
    if i + 5 > n {
        return false;
    }
    return int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82 && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82;
}

fn count_errors[&r](s: &r [byte], n: int) -> [] int {
    var i = 0;
    var count = 0;
    var counted = false;
    while i < n {
        if int_of(s[i]) == 10 {
            counted = false;
        } else if !counted && matches_at(s, n, i) {
            count = count + 1;
            counted = true;
        }
        i = i + 1;
    }
    return count;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);
    let (inp, outc) = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/data/input.log", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fs9szc5_/cache/result.txt");
    var status = 1;
    borrow mut heap as &!h in {
        let big = box_slice(h, 4194304, byte_of(0));
        var n = 0 - 1;
        borrow mut big as &!w in {
            borrow inp as &x in {
                n = load(x, contents(w));
            }
        }
        if n >= 0 {
            var count = 0;
            borrow big as &rd in {
                count = count_errors(contents(rd), n);
            }
            var text = buffer.empty(h, 32);
            text = buffer.push_nat(h, text, count);
            text = buffer.push(h, text, byte_of(10));
            borrow text as &t in {
                borrow mut io as &!i in {
                    say(i, buffer.bytes(t));
                }
                borrow outc as &y in {
                    store(y, buffer.bytes(t));
                }
            }
            buffer.drop(h, text);
            status = 0;
        }
        unbox_slice(h, big);
    }
    release(inp);
    release(outc);
    release(heap);
    release(io);
    return status;
}

