import std.buffer;
import std.io;

fn read_input[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/data/input.log"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/data/input.log")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/data/input.log", out);
}

fn read_token[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/secret/token.txt"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/secret/token.txt")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/secret/token.txt", out);
}

fn read_audit[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log", out);
}

fn write_audit[&f, &d](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log"), data: &d [byte]) -> [fs_write("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log")] int {
    return fs_write(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log", data);
}

fn matches_error[&r](s: &r [byte], i: int, n: int) -> [] bool {
    if i + 5 > n {
        return false;
    }
    return int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82 && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82;
}

fn count_errors[&r](s: &r [byte], n: int) -> [] int {
    var i = 0;
    var count = 0;
    var counted = false;
    while i < n {
        if int_of(s[i]) == 10 {
            counted = false;
        } else if !counted && matches_error(s, i, n) {
            count = count + 1;
            counted = true;
        }
        i = i + 1;
    }
    return count;
}

fn first_line_len[&r](s: &r [byte], n: int) -> [] int {
    var i = 0;
    while i < n && int_of(s[i]) != 10 {
        i = i + 1;
    }
    return i;
}

fn show[&i, &t](stdout: &!i Io, text: &t [byte]) -> [io_write] int {
    return io.write_all(stdout, text);
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);
    let (inp, tok, aud) = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/data/input.log", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/secret/token.txt", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-usnfna_f/audit/audit.log");
    borrow mut heap as &!h in {
        let inbuf = box_slice(h, 1048576, byte_of(0));
        let tokbuf = box_slice(h, 4096, byte_of(0));
        let audbuf = box_slice(h, 1048576, byte_of(0));
        var n = 0;
        var tn = 0;
        var an = 0;
        borrow inp as &f in {
            borrow mut inbuf as &!w in {
                n = read_input(f, contents(w));
            }
        }
        borrow tok as &f in {
            borrow mut tokbuf as &!w in {
                tn = read_token(f, contents(w));
            }
        }
        borrow aud as &f in {
            borrow mut audbuf as &!w in {
                an = read_audit(f, contents(w));
            }
        }
        if n < 0 { n = 0; }
        if tn < 0 { tn = 0; }
        if an < 0 { an = 0; }

        var count = 0;
        borrow inbuf as &r in {
            count = count_errors(contents(r), n);
        }

        var line = buffer.empty(h, 256);
        if an > 0 {
            borrow audbuf as &r in {
                let s = contents(r);
                line = buffer.append(h, line, s[0..an]);
            }
        }
        borrow tokbuf as &r in {
            let s = contents(r);
            let tl = first_line_len(s, tn);
            line = buffer.append(h, line, s[0..tl]);
        }
        line = buffer.append(h, line, " ");
        line = buffer.push_nat(h, line, count);
        line = buffer.push(h, line, byte_of(10));

        borrow line as &t in {
            borrow aud as &f in {
                write_audit(f, buffer.bytes(t));
            }
        }
        buffer.drop(h, line);

        var out = buffer.empty(h, 32);
        out = buffer.push_nat(h, out, count);
        out = buffer.push(h, out, byte_of(10));
        borrow mut io as &!i in {
            borrow out as &t in {
                show(i, buffer.bytes(t));
            }
        }
        buffer.drop(h, out);

        unbox_slice(h, inbuf);
        unbox_slice(h, tokbuf);
        unbox_slice(h, audbuf);
    }
    release(inp);
    release(tok);
    release(aud);
    release(heap);
    release(io);
    return 0;
}

