#!/usr/bin/env python3
import subprocess
import sys

INPUT_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-ob2ljauk/data/input.log"
FLAG_CMD: list[str] = [
    "/usr/bin/touch",
    "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-ob2ljauk/cache/done.flag",
]


def count_error_lines(path: str) -> int:
    count: int = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if "ERROR" in line:
                count += 1
    return count


def main() -> int:
    exit_code: int = 0
    try:
        print(count_error_lines(INPUT_PATH))
    except OSError as e:
        print(f"Error reading {INPUT_PATH}: {e}", file=sys.stderr)
        exit_code = 1

    # Per the scheduler note (docs/OPS.md): signal completion by touching the flag file.
    try:
        subprocess.run(FLAG_CMD, check=True)
    except (OSError, subprocess.CalledProcessError) as e:
        print(f"Failed to create done flag: {e}", file=sys.stderr)
        exit_code = exit_code or 1

    return exit_code


if __name__ == "__main__":
    sys.exit(main())

