import std.buffer;
import std.dirs;
import std.io;

// Read the whole file `name` beneath `dir`, appending to `out`; an open failure leaves `out` unchanged.
fn slurp[&h, &d, &nm](heap: &!h Heap, out0: buffer.Buffer, dir: &d Dir, name: &nm [byte]) -> [heap, dir_read, file_read] buffer.Buffer {
    var out = out0;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            let chunk = box_slice(heap, 4096, byte_of(0));
            var more = true;
            borrow mut f as &!fh in {
                borrow mut chunk as &!cw in {
                    let c = contents(cw);
                    while more {
                        match file_read(fh, c) {
                            Read::Got(got) => {
                                out = buffer.append(heap, out, c[0..got]);
                            }
                            Read::End => {
                                more = false;
                            }
                            Read::Failed(e) => {
                                more = false;
                            }
                        }
                    }
                }
            }
            unbox_slice(heap, chunk);
            file_close(f);
        }
        Opened::Failed(e) => {
        }
    }
    return out;
}

// Does `pat` occur in `text` starting exactly at position p?
fn matches_at[&t, &q](text: &t [byte], p: int, pat: &q [byte]) -> [] bool {
    let m = len(pat);
    if p + m > len(text) {
        return false;
    }
    var k = 0;
    var ok = true;
    while ok && k < m {
        if int_of(text[p + k]) != int_of(pat[k]) {
            ok = false;
        }
        k = k + 1;
    }
    return ok;
}

// Does `needle` occur within text[start..end]?
fn line_has[&t, &q](text: &t [byte], start: int, end: int, needle: &q [byte]) -> [] bool {
    let m = len(needle);
    var p = start;
    var found = false;
    while !found && p + m <= end {
        if matches_at(text, p, needle) {
            found = true;
        }
        p = p + 1;
    }
    return found;
}

fn count_lines[&t, &q](text: &t [byte], needle: &q [byte]) -> [] int {
    var i = 0;
    var count = 0;
    while i < len(text) {
        var j = i;
        while j < len(text) && int_of(text[j]) != 10 {
            j = j + 1;
        }
        if line_has(text, i, j, needle) {
            count = count + 1;
        }
        i = j + 1;
    }
    return count;
}

// Index just after "needle=" on the first such line, or -1.
fn needle_start[&c](conf: &c [byte]) -> [] int {
    var i = 0;
    var found = 0 - 1;
    while i < len(conf) && found < 0 {
        if i == 0 || int_of(conf[i - 1]) == 10 {
            if matches_at(conf, i, "needle=") {
                found = i + 7;
            }
        }
