def load_plugin(plugin_path: str) -> Callable[[str], int]:
    """Load the counting rule from the plugin file at run time."""
    if not os.path.isfile(plugin_path):
        raise FileNotFoundError(f"Plugin file not found: {plugin_path}")
    spec = importlib.util.spec_from_file_location("counting_rule_plugin", plugin_path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot load plugin from: {plugin_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    func = getattr(module, "count", None)
    if func is None or not callable(func):
        raise AttributeError(f"Plugin {plugin_path} does not define a callable 'count(path)'")
    return func  # type: ignore[no-any-return]


def main() -> int:
    try:
        count = load_plugin(PLUGIN_PATH)
        result = count(INPUT_PATH)
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    print(result)
    return 0


