fn step(s: int, c: int) -> [] int {
    if s == 5 {
        return 5;
    }
    if c == 69 {
        return 1;
    }
    if s == 1 && c == 82 {
        return 2;
    }
    if s == 2 && c == 82 {
        return 3;
    }
    if s == 3 && c == 79 {
        return 4;
    }
    if s == 4 && c == 82 {
        return 5;
    }
    return 0;
}

fn read_line[&h, &i](heap: &!h Heap, io: &!i Io) -> [heap, io_read] buffer.Buffer {
    var out = buffer.empty(heap, 64);
    var c = getchar(io);
    while c >= 0 && c != 10 {
        if c != 13 {
            out = buffer.push(heap, out, byte_of(c));
        }
        c = getchar(io);
    }
    return out;
}

fn count_errors[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    var total = 0 - 1;
    match confined.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            var lines = 0;
            var state = 0;
            var bad = false;
            var going = true;
            borrow mut f as &!h in {
                while going {
                    match file_read(h, into) {
                        Read::Got(n) => {
                            var k = 0;
                            while k < n {
                                let c = int_of(into[k]);
                                if c == 10 {
                                    if state == 5 {
                                        lines = lines + 1;
                                    }
                                    state = 0;
                                } else {
                                    state = step(state, c);
                                }
                                k = k + 1;
                            }
                        }
                        Read::End => {
                            going = false;
                        }
                        Read::Failed(e) => {
                            going = false;
                            bad = true;
                        }
                    }
                }
            }
            file_close(f);
            if !bad {
                if state == 5 {
                    lines = lines + 1;
                }
                total = lines;
            }
        }
        Opened::Failed(e) => {
        }
    }
    return total;
}

