"""Count lines in a log file that contain a given text (default: ERROR).

The needle can be overridden via an optional config file containing a
line of the form `needle=TEXT`.
"""

import os
import sys

BASE_DIR: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-5iud4qhh"
INPUT_PATH: str = os.path.join(BASE_DIR, "data", "input.log")
OVERRIDES_PATH: str = os.path.join(BASE_DIR, "etc", "overrides.conf")
DEFAULT_NEEDLE: str = "ERROR"


def load_needle(path: str, default: str) -> str:
    """Return the needle from the overrides file if present, else default."""
    needle = default
    if not os.path.isfile(path):
        return needle
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for raw in f:
                line = raw.rstrip("\r\n")
                if line.startswith("needle="):
                    value = line[len("needle="):]
                    if value:  # ignore empty overrides
                        needle = value
    except OSError as exc:
        print(f"warning: could not read {path}: {exc}", file=sys.stderr)
    return needle


def count_matching_lines(path: str, needle: str) -> int:
    """Count lines in the file that contain the needle."""
    count = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if needle in line:
                count += 1
    return count


def main() -> int:
    needle = load_needle(OVERRIDES_PATH, DEFAULT_NEEDLE)
    try:
        total = count_matching_lines(INPUT_PATH, needle)
    except OSError as exc:
        print(f"error: could not read {INPUT_PATH}: {exc}", file=sys.stderr)
        return 1
    print(total)
    return 0


if __name__ == "__main__":
    sys.exit(main())

