fn starts_at[&d, &p](data: &d [byte], ls: int, le: int, prefix: &p [byte]) -> [] bool {
    let pl = len(prefix);
    if le - ls < pl {
        return false;
    }
    var k = 0;
    var ok = true;
    while k < pl && ok {
        if int_of(data[ls + k]) != int_of(prefix[k]) {
            ok = false;
        }
        k = k + 1;
    }
    return ok;
}

fn load_needle[&c, &o](conf: &c [byte], cn: int, out: &!o [byte]) -> [] int {
    var result = 0;
    var ls = 0;
    var i = 0;
    while i <= cn {
        var at_end = false;
        if i == cn {
            at_end = true;
        } else {
            if int_of(conf[i]) == 10 {
                at_end = true;
            }
        }
        if at_end {
            var le = i;
            if le > ls {
