import std.dirs;
import std.io as sio;

// Read one line from stdin into `buf`; answer its length (without the newline).
fn read_name[&i, &b](io: &!i Io, buf: &!b [byte]) -> [io_read] int {
    var n = 0;
    var c = getchar(io);
    while c >= 0 && c != 10 {
        if n < len(buf) {
            buf[n] = byte_of(c);
            n = n + 1;
        }
        c = getchar(io);
    }
    if n > 0 && int_of(buf[n - 1]) == 13 {
        n = n - 1;
    }
    return n;
}

// The byte that advances the match of "ERROR" from `state`.
fn want(state: int) -> [] int {
    if state == 0 {
        return 69;
    }
    if state == 1 {
        return 82;
    }
    if state == 2 {
        return 82;
    }
    if state == 3 {
        return 79;
    }
    return 82;
}

// Count the lines of the file `name` beneath `dir` that contain ERROR.
// Answers -1 if the file cannot be opened safely or read.
fn count_errors[&d, &n, &b](dir: &d Dir, name: &n [byte], chunk: &!b [byte]) -> [dir_read, file_read] int {
    var lines = 0;
    var failed = false;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            var state = 0;
            var flag = 0;
            var done = false;
            borrow mut f as &!h in {
                while !done {
                    match file_read(h, chunk) {
                        Read::Got(got) => {
                            var i = 0;
                            while i < got {
                                let c = int_of(chunk[i]);
                                if c == 10 {
                                    if flag == 1 {
                                        lines = lines + 1;
                                    }
                                    flag = 0;
                                    state = 0;
                                } else if c == want(state) {
                                    state = state + 1;
                                    if state == 5 {
                                        flag = 1;
                                        state = 0;
                                    }
                                } else if c == 69 {
                                    state = 1;
                                } else {
                                    state = 0;
                                }
                                i = i + 1;
                            }
                        }
                        Read::End => {
                            done = true;
                        }
                        Read::Failed(e) => {
                            done = true;
                            failed = true;
                        }
                    }
                }
            }
            if flag == 1 {
                lines = lines + 1;
            }
            file_close(f);
        }
        Opened::Failed(e) => {
            failed = true;
        }
    }
    if failed {
        return 0 - 1;
    }
    return lines;
}

