    let Split { io, ffi, fs, heap, args, net, clock, signals, exec } = split(world);
    release(ffi);
    release(heap);
    release(args);
    release(net);
    release(clock);
    release(signals);
    release(exec);
    var status = 1;
    region r {
        let namebuf = alloc_slice[r](4096, byte_of(0));
        let chunk = alloc_slice[r](4096, byte_of(0));
        let digits = alloc_slice[r](24, byte_of(0));
        var n = 0;
        borrow mut io as &!i in {
            n = read_name(i, namebuf);
        }
        var count = 0 - 1;
        if n > 0 {
            let data = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-h73x4a7m/data");
            borrow data as &f in {
                match open_dir(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-h73x4a7m/data") {
                    DirOpened::Ok(d) => {
                        var held = d;
                        borrow held as &dd in {
                            let name = namebuf[0..n];
                            count = count_errors(dd, name, chunk);
                        }
                        dir_close(held);
                    }
                    DirOpened::Failed(e) => {
                    }
                }
            }
            release(data);
        } else {
            release(fs);
        }
        if count >= 0 {
            digits[23] = byte_of(10);
            var pos = 23;
            if count == 0 {
                pos = 22;
                digits[22] = byte_of(48);
            } else {
                var m = count;
                while m > 0 {
                    pos = pos - 1;
                    digits[pos] = byte_of(48 + m % 10);
                    m = m / 10;
                }
            }
            borrow mut io as &!o in {
                sio.write_all(o, digits[pos..24]);
            }
            status = 0;
        }
    }
    release(io);
    return status;
}

