// Count the lines of `name` (beneath `dir`) that contain ERROR, reading in
// chunks through `into`. Returns -1 if the file cannot be opened or read.
fn count_file[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    var count = 0;
    var flag = false;
    var m = 0;
    var failed = false;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            borrow mut f as &!h in {
                var more = true;
                while more {
                    match file_read(h, into) {
                        Read::Got(k) => {
                            var i = 0;
                            while i < k {
                                let c = int_of(into[i]);
                                if c == 10 {
                                    if flag {
                                        count = count + 1;
                                    }
                                    flag = false;
                                    m = 0;
                                } else if m == 0 && c == 'E' {
                                    m = 1;
                                } else if m == 1 && c == 'R' {
                                    m = 2;
                                } else if m == 2 && c == 'R' {
                                    m = 3;
                                } else if m == 3 && c == 'O' {
                                    m = 4;
                                } else if m == 4 && c == 'R' {
                                    flag = true;
                                    m = 0;
                                } else if c == 'E' {
                                    m = 1;
                                } else {
                                    m = 0;
                                }
                                i = i + 1;
                            }
                            if k == 0 {
                                more = false;
                            }
                        }
                        Read::End => {
                            more = false;
                        }
                        Read::Failed(e) => {
                            failed = true;
                            more = false;
                        }
                    }
                }
            }
            file_close(f);
        }
        Opened::Failed(e) => {
            failed = true;
        }
    }
    if failed {
        return 0 - 1;
    }
    if flag {
        count = count + 1;
    }
    return count;
}

