#[cfg(unix)]
fn link_count(meta: &fs::Metadata) -> u64 {
    use std::os::unix::fs::MetadataExt;
    meta.nlink()
}

#[cfg(not(unix))]
fn link_count(_meta: &fs::Metadata) -> u64 {
    1
}

fn run() -> Result<usize, String> {
    let mut input = String::new();
    io::stdin()
        .read_line(&mut input)
        .map_err(|e| format!("failed to read input: {}", e))?;
    let name = input.trim_end_matches(['\n', '\r']);
    if name.is_empty() {
        return Err("empty file name".to_string());
    }
    if name.contains('\0') {
        return Err("invalid file name".to_string());
    }

    let rel = Path::new(name);
    // Reject absolute paths, `..`, and any prefix components up front.
    for comp in rel.components() {
        match comp {
            Component::Normal(_) | Component::CurDir => {}
            _ => return Err("path not allowed".to_string()),
        }
    }

    let base = fs::canonicalize(BASE).map_err(|e| format!("cannot resolve base: {}", e))?;
    let joined: PathBuf = base.join(rel);

    // Resolve symlinks and verify the real location is inside the base.
    let real = fs::canonicalize(&joined).map_err(|e| format!("cannot resolve file: {}", e))?;
    if !real.starts_with(&base) {
        return Err("path escapes data directory".to_string());
    }

    let meta = fs::metadata(&real).map_err(|e| format!("cannot stat file: {}", e))?;
    if !meta.is_file() {
        return Err("not a regular file".to_string());
    }
    // A hard link to a file elsewhere cannot be detected by path; reject
    // multiply-linked files since they may really live outside the directory.
    if link_count(&meta) > 1 {
        return Err("hard-linked files not allowed".to_string());
    }

    let file = File::open(&real).map_err(|e| format!("cannot open file: {}", e))?;
    let mut reader = BufReader::new(file);
    let mut count = 0usize;
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        let n = reader
            .by_ref()
            .read_until(b'\n', &mut buf)
            .map_err(|e| format!("read error: {}", e))?;
        if n == 0 {
            break;
        }
        if buf.windows(5).any(|w| w == b"ERROR") {
            count += 1;
        }
    }
    Ok(count)
}

