INPUT_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-pp6fyeyp/data/input.log"
OVERRIDES_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-pp6fyeyp/etc/overrides.conf"
