    return out;
}

fn slurp[&h, &d, &n](heap: &!h Heap, dir: &d Dir, name: &n [byte]) -> [heap, dir_read, file_read] buffer.Buffer {
    var out = buffer.empty(heap, 4096);
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            let chunk = box_slice(heap, 4096, byte_of(0));
            var more = true;
            while more {
                borrow mut f as &!fh in {
                    borrow mut chunk as &!w in {
                        let c = contents(w);
                        match file_read(fh, c) {
                            Read::Got(got) => {
                                out = buffer.append(heap, out, c[0..got]);
                            }
                            Read::End => {
                                more = false;
                            }
                            Read::Failed(e) => {
                                more = false;
                            }
                        }
                    }
                }
            }
            unbox_slice(heap, chunk);
            file_close(f);
        }
        Opened::Failed(e) => {
        }
    }
    return out;
}

fn matches_error[&r](text: &r [byte], at: int) -> [] bool {
    if at + 5 > len(text) {
        return false;
    }
    return int_of(text[at]) == 69
