fn say[&i, &t](out: &!i Io, text: &t [byte]) -> [io_write] int {
    return io.write_all(out, text);
}

fn matches_at[&a, &b](hay: &a [byte], i: int, hi: int, needle: &b [byte]) -> [] bool {
    let m = len(needle);
    if i + m > hi {
        return false;
    }
    var j = 0;
    var ok = true;
    while j < m && ok {
        if int_of(hay[i + j]) != int_of(needle[j]) {
            ok = false;
        }
        j = j + 1;
    }
    return ok;
}

fn has_needle[&a, &b](hay: &a [byte], s: int, e: int, needle: &b [byte]) -> [] bool {
    var i = s;
    var found = false;
    while i + len(needle) <= e && !found {
        if matches_at(hay, i, e, needle) {
            found = true;
        }
        i = i + 1;
    }
    return found;
}

fn line_end[&a](text: &a [byte], s: int) -> [] int {
    var i = s;
    while i < len(text) && int_of(text[i]) != 10 {
        i = i + 1;
    }
    return i;
}

fn count_lines[&a, &b](text: &a [byte], needle: &b [byte]) -> [] int {
    var s = 0;
    var n = 0;
    while s < len(text) {
        let e = line_end(text, s);
        if has_needle(text, s, e, needle) {
            n = n + 1;
        }
        s = e + 1;
    }
    return n;
}

// Last `needle=TEXT` line wins; returns start (want_end == 0) or end (want_end == 1) of TEXT, or -1.
fn override_span[&a](text: &a [byte], want_end: int) -> [] int {
    var s = 0;
    var found = 0 - 1;
    while s < len(text) {
        let e = line_end(text, s);
        var te = e;
        if te > s && int_of(text[te - 1]) == 13 {
            te = te - 1;
        }
        if te - s > 7 && matches_at(text, s, te, "needle=") {
            if want_end == 1 {
                found = te;
            } else {
                found = s + 7;
            }
        }
        s = e + 1;
    }
    return found;
}

