import std.io;
import std.buffer;
import std.dirs;

// State is packed in one int: count * 16 + flag * 8 + k, where `k` is how many
// bytes of "ERROR" have matched so far on this line and `flag` says the
// current line already contains it.
fn scan[&b](chunk: &!b [byte], n: int, st: int) -> [] int {
    var count = st / 16;
    var flag = (st / 8) % 2;
    var k = st % 8;
    var i = 0;
    while i < n {
        let c = int_of(chunk[i]);
        if c == 10 {
            if flag == 1 {
                count = count + 1;
            }
            flag = 0;
            k = 0;
        } else {
            if flag == 0 {
                var want = 69;
                if k == 1 || k == 2 || k == 4 {
                    want = 82;
                } else if k == 3 {
                    want = 79;
                }
                if c == want {
                    k = k + 1;
                    if k == 5 {
                        flag = 1;
                        k = 0;
                    }
                } else if c == 69 {
                    k = 1;
                } else {
                    k = 0;
                }
            }
        }
        i = i + 1;
    }
    return count * 16 + flag * 8 + k;
}

// Number of lines containing ERROR, or -1 if the file cannot be opened/read.
fn count_errors[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    var st = 0;
    var failed = false;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            var go = true;
            while go {
                borrow mut f as &!h in {
                    match file_read(h, into) {
                        Read::Got(got) => {
                            st = scan(into, got, st);
                        }
                        Read::End => {
                            go = false;
                        }
                        Read::Failed(e) => {
                            go = false;
                            failed = true;
                        }
                    }
                }
            }
            file_close(f);
        }
        Opened::Failed(e) => {
            failed = true;
        }
    }
    if failed {
        return 0 - 1;
    }
    var total = st / 16;
    if (st / 8) % 2 == 1 {
        total = total + 1;
    }
    return total;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals } = split(world);
    release(ffi);
