// The byte that advances the match of "ERROR" from the given state.
fn want(state: int) -> [] int {
    if state == 0 {
        return 69;
    }
    if state == 1 {
        return 82;
    }
    if state == 2 {
        return 82;
    }
    if state == 3 {
        return 79;
    }
    return 82;
}

// Count the lines of `name` (beneath `dir`) that contain "ERROR", or answer -1.
fn count_error_lines[&d, &n](dir: &d Dir, name: &n [byte]) -> [dir_read, file_read] int {
    var count = 0;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            borrow mut f as &!h in {
                region r {
