                                        } else if c == 69 {
                                            state = 1;
                                        } else {
                                            state = 0;
                                        }
                                    }
                                    i = i + 1;
                                }
                            }
                            Read::End => {
                                if found {
                                    count = count + 1;
                                }
                                done = true;
                            }
                            Read::Failed(e) => {
