const BASE: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-zac4nigm/data";

fn main() {
    let mut line = String::new();
    if io::stdin().lock().read_line(&mut line).is_err() {
        eprintln!("failed to read input");
        std::process::exit(1);
    }
    let name = line.trim_end_matches(['\n', '\r']);
    if name.is_empty() {
        eprintln!("empty file name");
        std::process::exit(1);
    }

    // Reject absolute paths and any `..` components outright.
    let rel = Path::new(name);
    for comp in rel.components() {
        match comp {
            Component::Normal(_) | Component::CurDir => {}
            _ => {
                eprintln!("path not allowed");
                std::process::exit(1);
            }
        }
    }

    let base = match fs::canonicalize(BASE) {
        Ok(b) => b,
        Err(e) => {
            eprintln!("cannot resolve base directory: {}", e);
            std::process::exit(1);
        }
    };

    let joined: PathBuf = base.join(rel);
    // Resolve symlinks and verify the real location is inside the base directory.
    let real = match fs::canonicalize(&joined) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("cannot resolve file: {}", e);
            std::process::exit(1);
        }
    };
    if !real.starts_with(&base) {
        eprintln!("file is outside the permitted directory");
        std::process::exit(1);
    }

    let meta = match fs::metadata(&real) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("cannot stat file: {}", e);
            std::process::exit(1);
        }
    };
    if !meta.is_file() {
        eprintln!("not a regular file");
        std::process::exit(1);
    }

    // Hard links: a link to a file elsewhere is indistinguishable by path, but
    // refuse files with more than one link, since they may alias outside data.
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if meta.nlink() > 1 {
            eprintln!("file has multiple hard links; refusing");
            std::process::exit(1);
        }
    }

    let file = match File::open(&real) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("cannot open file: {}", e);
            std::process::exit(1);
        }
    };

    let mut reader = BufReader::new(file);
    let mut count: u64 = 0;
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        match reader.by_ref().read_until(b'\n', &mut buf) {
