// Read one line of standard input into `into`; answer how many bytes it holds.
fn read_line[&i, &b](io: &!i Io, into: &!b [byte]) -> [io_read] int {
    var n = 0;
    var c = getchar(io);
    while c >= 0 && c != 10 && n < len(into) {
        into[n] = byte_of(c);
        n = n + 1;
        c = getchar(io);
    }
    return n;
}

// Count the lines of the file `name` (beneath `dir`) that contain "ERROR".
// Answers -1 if the file cannot be opened or read.
fn count_in[&d, &n](dir: &d Dir, name: &n [byte]) -> [dir_read, file_read] int {
    var total = 0;
    match confined.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            region r {
                let chunk = alloc_slice[r](4096, byte_of(0));
                var going = true;
                var state = 0;
                var counted = false;
                borrow mut f as &!h in {
                    while going {
                        match file_read(h, chunk) {
                            Read::Got(m) => {
                                var k = 0;
                                while k < m {
                                    let c = int_of(chunk[k]);
                                    if c == 10 {
                                        state = 0;
                                        counted = false;
                                    } else {
                                        if state == 0 {
                                            if c == 69 { state = 1; }
                                        } else if state == 1 {
                                            if c == 82 { state = 2; } else if c == 69 { state = 1; } else { state = 0; }
                                        } else if state == 2 {
                                            if c == 82 { state = 3; } else if c == 69 { state = 1; } else { state = 0; }
                                        } else if state == 3 {
                                            if c == 79 { state = 4; } else if c == 69 { state = 1; } else { state = 0; }
                                        } else {
                                            if c == 82 {
                                                if !counted {
                                                    total = total + 1;
                                                    counted = true;
                                                }
                                                state = 0;
                                            } else if c == 69 { state = 1; } else { state = 0; }
                                        }
                                    }
                                    k = k + 1;
                                }
                            }
                            Read::End => {
                                going = false;
                            }
                            Read::Failed(e) => {
                                going = false;
                                total = 0 - 1;
                            }
                        }
                    }
                }
            }
            file_close(f);
        }
        Opened::Failed(e) => {
            total = 0 - 1;
        }
    }
    return total;
}

