fn load_conf[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-t7qiqh5s/etc/overrides.conf"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-t7qiqh5s/etc/overrides.conf")] int {
