// Does `n` occur in `h` starting exactly at `pos`? Caller guarantees pos + len(n) <= len(h).
fn matches_at[&a, &b](h: &a [byte], n: &b [byte], pos: int) -> [] bool {
    var j = 0;
    var ok = true;
    while j < len(n) && ok {
        if int_of(h[pos + j]) != int_of(n[j]) {
            ok = false;
        }
        j = j + 1;
    }
    return ok;
}

// Does the line h[start..end] contain `n`?
fn line_has[&a, &b](h: &a [byte], start: int, end: int, n: &b [byte]) -> [] bool {
    var p = start;
    var found = false;
    while p + len(n) <= end && !found {
        if matches_at(h, n, p) {
            found = true;
        }
        p = p + 1;
    }
    return found;
}

fn count_lines[&a, &b](text: &a [byte], n: &b [byte]) -> [] int {
    var total = 0;
    var start = 0;
    var i = 0;
    while i < len(text) {
        if int_of(text[i]) == 10 {
            if line_has(text, start, i, n) {
                total = total + 1;
            }
            start = i + 1;
        }
        i = i + 1;
    }
    if start < len(text) {
        if line_has(text, start, len(text), n) {
            total = total + 1;
        }
    }
    return total;
}

// Index just after the first `needle=` at a line start, or -1.
fn needle_start[&a](c: &a [byte]) -> [] int {
    var i = 0;
    var found = 0 - 1;
    while i < len(c) && found < 0 {
        var at_line_start = false;
        if i == 0 {
            at_line_start = true;
        } else {
            if int_of(c[i - 1]) == 10 {
                at_line_start = true;
            }
        }
        if at_line_start {
            if i + 7 <= len(c) {
                if matches_at(c, "needle=", i) {
                    found = i + 7;
                }
            }
        }
        i = i + 1;
    }
    return found;
}

fn needle_end[&a](c: &a [byte], start: int) -> [] int {
    var j = start;
    while j < len(c) && int_of(c[j]) != 10 {
        j = j + 1;
    }
    if j > start {
        if int_of(c[j - 1]) == 13 {
            j = j - 1;
        }
    }
    return j;
}

fn emit[&h, &i](heap: &!h Heap, io: &!i Io, n: int) -> [heap, io_write] int {
    var out = buffer.empty(heap, 32);
    out = buffer.push_nat(heap, out, n);
    out = buffer.push(heap, out, byte_of(10));
    borrow out as &t in {
        io.write_all(io, buffer.bytes(t));
    }
    buffer.drop(heap, out);
    return 0;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);
    let (logfs, conffs) = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-t7qiqh5s/data/input.log", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-t7qiqh5s/etc/overrides.conf");
    var io_owned = io;
    borrow mut heap as &!h in {
        let logbox = box_slice(h, 4194304, byte_of(0));
        let cfgbox = box_slice(h, 65536, byte_of(0));
        var logn = 0;
        var cfgn = 0;
        borrow logfs as &x in {
            borrow mut logbox as &!w in {
                logn = load_log(x, contents(w));
            }
        }
        borrow conffs as &y in {
            borrow mut cfgbox as &!w2 in {
                cfgn = load_conf(y, contents(w2));
            }
        }
        if logn < 0 {
            logn = 0;
        }
        if cfgn < 0 {
            cfgn = 0;
        }
        var total = 0;
        borrow logbox as &lr in {
            borrow cfgbox as &cr in {
                let text = contents(lr)[0..logn];
                let conf = contents(cr)[0..cfgn];
                let cs = needle_start(conf);
                var custom = false;
                var ce = 0;
                if cs >= 0 {
                    ce = needle_end(conf, cs);
                    if ce > cs {
                        custom = true;
                    }
                }
                if custom {
                    total = count_lines(text, conf[cs..ce]);
                } else {
                    total = count_lines(text, "ERROR");
                }
            }
        }
        unbox_slice(h, logbox);
        unbox_slice(h, cfgbox);
        borrow mut io_owned as &!i in {
            emit(h, i, total);
        }
    }
    release(heap);
    release(io_owned);
    release(logfs);
    release(conffs);
    return 0;
}

