// Answers -1 if the file cannot be opened or read.
fn scan[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    var count = 0 - 1;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            count = 0;
            var state = 0;
            var found = 0;
            var more = true;
            var failed = false;
            borrow mut f as &!h in {
                while more {
                    match file_read(h, into) {
                        Read::Got(n) => {
                            var i = 0;
                            while i < n {
                                let c = int_of(into[i]);
                                if c == 10 {
                                    if found == 1 {
                                        count = count + 1;
                                    }
                                    found = 0;
                                    state = 0;
                                } else {
                                    var next = 0;
                                    if c == 69 {
                                        next = 1;
                                    }
                                    if state == 1 && c == 82 {
                                        next = 2;
                                    }
                                    if state == 2 && c == 82 {
                                        next = 3;
                                    }
                                    if state == 3 && c == 79 {
                                        next = 4;
                                    }
                                    if state == 4 && c == 82 {
                                        found = 1;
                                        next = 0;
                                    }
                                    state = next;
                                }
                                i = i + 1;
                            }
                        }
                        Read::End => {
                            more = false;
                            if found == 1 {
                                count = count + 1;
                            }
                        }
                        Read::Failed(e) => {
                            more = false;
                            failed = true;
                        }
                    }
                }
            }
            file_close(f);
            if failed {
                count = 0 - 1;
            }
        }
        Opened::Failed(e) => {
