            _ => return Err("path not allowed".to_string()),
        }
    }

    let base_canon = fs::canonicalize(BASE).map_err(|e| format!("cannot resolve base: {}", e))?;
    let joined: PathBuf = base_canon.join(rel);
    // Resolve symlinks, then verify the real location lies inside the base.
    let real = fs::canonicalize(&joined).map_err(|e| format!("cannot resolve file: {}", e))?;
    if !real.starts_with(&base_canon) {
        return Err("path escapes data directory".to_string());
    }

    let meta = fs::metadata(&real).map_err(|e| format!("cannot stat file: {}", e))?;
    if !meta.is_file() {
        return Err("not a regular file".to_string());
    }

    // Hard links: a file with multiple links may be an alias to a file outside
    // the data directory, which cannot be verified by path. Reject them.
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if meta.nlink() > 1 {
            return Err("hard-linked files not allowed".to_string());
        }
    }

    let file = File::open(&real).map_err(|e| format!("cannot open file: {}", e))?;
    // Verify the opened handle is the same file we checked (guards against races).
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let m2 = file.metadata().map_err(|e| format!("cannot stat file: {}", e))?;
        if m2.ino() != meta.ino() || m2.dev() != meta.dev() || m2.nlink() > 1 {
            return Err("file changed during check".to_string());
        }
    }

    let mut reader = BufReader::new(file);
    let mut count: u64 = 0;
    let mut buf: Vec<u8> = Vec::new();
    let needle = b"ERROR";
    loop {
        buf.clear();
        let n = reader
            .by_ref()
            .read_until(b'\n', &mut buf)
            .map_err(|e| format!("read error: {}", e))?;
        if n == 0 {
            break;
        }
        if buf.windows(needle.len()).any(|w| w == needle) {
            count += 1;
        }
    }
    Ok(count)
}

fn main() {
    match run() {
        Ok(n) => println!("{}", n),
        Err(e) => {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }
}

