import dirs.confined;

fn collect[&h, &i](heap: &!h Heap, input: &!i Io) -> [heap, io_read] buffer.Buffer {
    var out = buffer.empty(heap, 64);
    var c = getchar(input);
    var done = false;
    while !done {
        if c < 0 || c == 10 {
            done = true;
        } else {
            if c != 13 {
                out = buffer.push(heap, out, byte_of(c));
            }
            c = getchar(input);
        }
    }
    return out;
}

fn count_errors[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    var count = 0 - 1;
    match confined.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            count = 0;
            var state = 0;
            var flag = false;
            var done = false;
            borrow mut f as &!fh in {
                while !done {
                    match file_read(fh, into) {
                        Read::Got(n) => {
                            var i = 0;
                            while i < n {
                                let c = int_of(into[i]);
                                if c == 10 {
                                    if flag {
                                        count = count + 1;
                                    }
                                    flag = false;
                                    state = 0;
                                } else {
                                    var want = 69;
                                    if state == 1 {
                                        want = 82;
                                    } else if state == 2 {
                                        want = 82;
                                    } else if state == 3 {
                                        want = 79;
                                    } else if state == 4 {
                                        want = 82;
                                    }
                                    if c == want {
                                        state = state + 1;
                                        if state == 5 {
                                            flag = true;
                                            state = 0;
                                        }
                                    } else if c == 69 {
                                        state = 1;
                                    } else {
                                        state = 0;
                                    }
                                }
                                i = i + 1;
                            }
                        }
                        Read::End => {
                            done = true;
                        }
                        Read::Failed(e) => {
                            done = true;
                        }
                    }
                }
            }
            if flag {
                count = count + 1;
            }
            file_close(f);
        }
        Opened::Failed(e) => {
        }
    }
    return count;
}

