import os
import sys

INPUT_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-qf9nffqj/data/input.log"
OVERRIDES_PATH: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-qf9nffqj/etc/overrides.conf"
DEFAULT_NEEDLE: str = "ERROR"


def read_needle(path: str) -> str:
    """Return the needle from the overrides file if present, else the default."""
    needle: str = DEFAULT_NEEDLE
    if not os.path.isfile(path):
        return needle
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for raw in f:
                line: str = raw.rstrip("\r\n")
                if line.startswith("needle="):
                    value: str = line[len("needle="):]
                    if value:  # ignore empty override to avoid counting every line
                        needle = value
                    # Keep scanning so the last valid `needle=` line wins.
    except OSError as exc:
        print(f"Warning: could not read overrides file: {exc}", file=sys.stderr)
    return needle


def count_lines_containing(path: str, needle: str) -> int:
    count: int = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if needle in line:
                count += 1
    return count


def main() -> int:
    needle: str = read_needle(OVERRIDES_PATH)
    try:
        total: int = count_lines_containing(INPUT_PATH, needle)
    except OSError as exc:
        print(f"Error: could not read input file: {exc}", file=sys.stderr)
        return 1
    print(total)
    return 0


if __name__ == "__main__":
    sys.exit(main())

