import std.buffer;
import std.dirs;
import std.io;

// Next KMP-style state for the pattern "ERROR". The failure function of
// this pattern is all zeros, so on a mismatch the state is 0, or 1 when
// the byte itself is 'E'.
fn expect(k: int) -> [] int {
    if k == 0 {
        return 69;
    }
    if k == 1 || k == 2 || k == 4 {
        return 82;
    }
    return 79;
}

fn step(k: int, c: int) -> [] int {
    if c == expect(k) {
        return k + 1;
    }
    if c == 69 {
        return 1;
    }
    return 0;
}

fn read_name[&h, &i](heap: &!h Heap, io: &!i Io) -> [heap, io_read] buffer.Buffer {
    var out = buffer.empty(heap, 64);
    var c = getchar(io);
    while c >= 0 && c != 10 {
        if c != 13 {
            out = buffer.push(heap, out, byte_of(c));
        }
        c = getchar(io);
    }
    return out;
}

// Number of lines of the named file containing ERROR, or -1 if the file
// cannot be read or is refused by the directory handle.
fn count_file[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    if len(name) == 0 {
        return 0 - 1;
    }
    var count = 0 - 1;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            var total = 0;
            var k = 0;
            var counted = false;
            var done = false;
            var failed = false;
            borrow mut f as &!h in {
                while !done {
                    match file_read(h, into) {
                        Read::Got(got) => {
                            var i = 0;
                            while i < got {
                                let c = int_of(into[i]);
                                if c == 10 {
                                    k = 0;
                                    counted = false;
                                } else {
                                    k = step(k, c);
                                    if k == 5 {
                                        k = 0;
                                        if !counted {
                                            counted = true;
                                            total = total + 1;
                                        }
                                    }
                                }
                                i = i + 1;
                            }
                        }
                        Read::End => {
                            done = true;
                        }
                        Read::Failed(e) => {
                            done = true;
                            failed = true;
                        }
                    }
                }
            }
            file_close(f);
            if !failed {
                count = total;
            }
        }
        Opened::Failed(e) => {
        }
    }
    return count;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals, exec, tty } = split(world);
    release(ffi); release(args); release(net); release(clock); release(signals); release(exec); release(tty);
    let data = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7xh__4m0/data");
    var status = 1;
    borrow mut heap as &!h in {
        borrow mut io as &!i in {
            let name = read_name(h, i);
            var result = 0 - 1;
            borrow data as &f in {
                match open_dir(f, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-7xh__4m0/data") {
                    DirOpened::Ok(d) => {
                        var held = d;
                        let chunk = box_slice(h, 4096, byte_of(0));
                        borrow held as &dd in {
                            borrow name as &nb in {
                                borrow mut chunk as &!w in {
                                    result = count_file(dd, buffer.bytes(nb), contents(w));
                                }
                            }
                        }
                        unbox_slice(h, chunk);
                        dir_close(held);
                    }
                    DirOpened::Failed(e) => {
                    }
                }
            }
            buffer.drop(h, name);
            if result >= 0 {
                var out = buffer.empty(h, 16);
                out = buffer.push_nat(h, out, result);
                out = buffer.push(h, out, byte_of(10));
                borrow out as &t in {
                    io.write_all(i, buffer.bytes(t));
                }
                buffer.drop(h, out);
                status = 0;
            }
        }
    }
    release(data);
    release(heap);
    release(io);
    return status;
}

