fn is_error_at[&r](s: &r [byte], i: int) -> [] bool {
    if i + 5 > len(s) {
        return false;
    }
    return int_of(s[i]) == 69 && int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82
        && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82;
}

fn count_error_lines[&r](s: &r [byte], n: int) -> [] int {
    var i = 0;
    var count = 0;
    var found = false;
    while i < n {
        if int_of(s[i]) == 10 {
            if found {
                count = count + 1;
            }
            found = false;
        } else if !found && is_error_at(s, i) {
            found = true;
        }
        i = i + 1;
    }
    if found {
        count = count + 1;
    }
    return count;
}

