import std.io;
import std.buffer;

// Does `needle` occur in `hay` starting exactly at index `at`?
fn matches_at[&a, &b](hay: &a [byte], at: int, needle: &b [byte]) -> [] bool {
    if at + len(needle) > len(hay) {
        return false;
    }
    var j = 0;
    var ok = true;
    while j < len(needle) && ok {
        if int_of(hay[at + j]) != int_of(needle[j]) {
            ok = false;
        }
        j = j + 1;
    }
    return ok;
}

// Does the line data[start..end] contain `needle`?
fn line_has[&a, &b](data: &a [byte], start: int, end: int, needle: &b [byte]) -> [] bool {
    var i = start;
    var found = false;
    while i + len(needle) <= end && !found {
        if matches_at(data, i, needle) {
            found = true;
        }
        i = i + 1;
    }
    return found;
}

// Count the lines in data[0..n] that contain `needle`.
fn count_lines[&a, &b](data: &a [byte], n: int, needle: &b [byte]) -> [] int {
    var count = 0;
    var start = 0;
    var i = 0;
    while i <= n {
        if i == n || int_of(data[i]) == 10 {
            if line_has(data, start, i, needle) {
                count = count + 1;
            }
            start = i + 1;
        }
        i = i + 1;
    }
    return count;
}

// Start index of the text after `needle=` on the last such line, or -1.
fn needle_start[&a](conf: &a [byte], n: int) -> [] int {
    var found = 0 - 1;
    var start = 0;
    var i = 0;
    while i <= n {
        if i == n || int_of(conf[i]) == 10 {
            if i - start > 7 && matches_at(conf, start, "needle=") {
                found = start + 7;
            }
            start = i + 1;
        }
        i = i + 1;
    }
    return found;
}

// End index (exclusive) of the line beginning before `from`, trimming a trailing CR.
fn needle_end[&a](conf: &a [byte], from: int, n: int) -> [] int {
    var e = from;
    while e < n && int_of(conf[e]) != 10 {
        e = e + 1;
    }
    if e > from && int_of(conf[e - 1]) == 13 {
        e = e - 1;
    }
    return e;
}

