edition 9;

import std.dirs;
import std.buffer;
import std.io;

fn read_name[&h, &i](heap: &!h Heap, io: &!i Io) -> [heap, io_read] buffer.Buffer {
    var out = buffer.empty(heap, 64);
    var c = getchar(io);
    while c >= 0 && c != 10 {
        out = buffer.push(heap, out, byte_of(c));
        c = getchar(io);
    }
    return out;
}

fn step(k: int, c: int) -> [] int {
    var want = 69;
    if k == 1 {
        want = 82;
    }
    if k == 2 {
        want = 82;
    }
    if k == 3 {
        want = 79;
    }
    if k == 4 {
        want = 82;
    }
    if c == want {
        return k + 1;
    }
    if c == 69 {
        return 1;
    }
    return 0;
}

// Number of lines containing ERROR in the file `name` beneath `dir`, or -1.
fn count_errors[&d, &n, &b](dir: &d Dir, name: &n [byte], into: &!b [byte]) -> [dir_read, file_read] int {
    var total = 0;
    var failed = false;
    match dirs.open_file(dir, name) {
        Opened::Ok(file) => {
            var f = file;
            var k = 0;
            var found = false;
            var more = true;
            borrow mut f as &!h in {
                while more {
                    match file_read(h, into) {
                        Read::Got(got) => {
                            if got <= 0 {
                                more = false;
                            } else {
                                var i = 0;
                                while i < got {
                                    let c = int_of(into[i]);
                                    if c == 10 {
                                        if found {
                                            total = total + 1;
                                        }
                                        found = false;
                                        k = 0;
                                    } else {
                                        k = step(k, c);
                                        if k == 5 {
                                            found = true;
                                            k = 0;
                                        }
                                    }
                                    i = i + 1;
                                }
                            }
                        }
                        Read::End => {
                            more = false;
                        }
                        Read::Failed(e) => {
                            failed = true;
                            more = false;
                        }
                    }
                }
            }
            file_close(f);
            if found {
                total = total + 1;
            }
        }
        Opened::Failed(e) => {
            failed = true;
        }
    }
    if failed {
        return 0 - 1;
    }
    return total;
}

fn print_count[&h, &i](heap: &!h Heap, io: &!i Io, n: int) -> [heap, io_write] int {
    var out = buffer.empty(heap, 24);
    out = buffer.push_nat(heap, out, n);
    out = buffer.push(heap, out, byte_of(10));
    var r = 0;
    borrow out as &t in {
        r = io.write_all(io, buffer.bytes(t));
    }
    buffer.drop(heap, out);
    return r;
}

